import pytest

import tapedeck.engine.tape as tape


def _valid_tape():
    return {
        "session": {
            "sdk": "tapedeck-python",
            "captured_at": "2026-01-02T03:04:05Z",
            "duration_s": 1.25,
        },
        "timeline": [
            {"seq": 0, "t": 0.0, "dir": "in", "method": "ping"},
            {"seq": 1, "t": 0.1, "dir": "out", "value": "pong"},
        ],
        "mocked_modules": {
            "example.Client_result": {
                "methods": {
                    "fetch": {"return_value": {"ok": True}},
                }
            }
        },
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def test_required_keys_constant_matches_documented_contract():
    assert tape.REQUIRED_KEYS == (
        "session",
        "timeline",
        "mocked_modules",
        "metadata",
    )


def test_validate_tape_accepts_complete_tape_and_optional_sections():
    document = _valid_tape()
    document["value_index"] = {"value-1": {"answer": 42}}
    document["nested_schemas"] = {"example.Client_result": {"type": "object"}}
    document["hierarchical_bindings"] = {
        "example.Client_result": "example.Client"
    }

    assert tape.validate_tape(document) is None


def test_validate_tape_does_not_require_value_index_or_optional_sections():
    assert tape.validate_tape(_valid_tape()) is None


@pytest.mark.parametrize("missing_key", tape.REQUIRED_KEYS)
def test_validate_tape_rejects_each_missing_required_top_level_key(missing_key):
    document = _valid_tape()
    del document[missing_key]

    with pytest.raises(ValueError):
        tape.validate_tape(document)


def test_validate_tape_rejects_non_list_timeline():
    document = _valid_tape()
    document["timeline"] = {"seq": 0, "t": 0.0, "dir": "in"}

    with pytest.raises(ValueError):
        tape.validate_tape(document)


@pytest.mark.parametrize("bad_direction", ["", "incoming", "OUT", None, 0])
def test_validate_tape_rejects_unknown_timeline_directions(bad_direction):
    document = _valid_tape()
    document["timeline"] = [{"seq": 0, "t": 0.0, "dir": bad_direction}]

    with pytest.raises(ValueError):
        tape.validate_tape(document)


@pytest.mark.parametrize(
    "event",
    [
        {"t": 0.0, "dir": "in"},
        {"seq": 0, "dir": "in"},
        {"seq": 0, "t": 0.0},
    ],
)
def test_validate_tape_rejects_timeline_events_missing_shape_fields(event):
    document = _valid_tape()
    document["timeline"] = [event]

    with pytest.raises(ValueError):
        tape.validate_tape(document)


def test_infer_hierarchical_bindings_finds_each_capitalized_result_prefix():
    paths = [
        "api.Client_result",
        "api.Client_result.fetch",
        "api.Client_result.Session_result.request",
        "api.Other_result.call",
        "api.lowercase_result.call",
        "api.Client_resultish.call",
    ]

    assert tape.infer_hierarchical_bindings(paths) == {
        "api.Client_result": "api.Client",
        "api.Client_result.Session_result": "api.Client_result.Session",
        "api.Other_result": "api.Other",
    }


def test_infer_hierarchical_bindings_deduplicates_repeated_prefixes():
    paths = [
        "pkg.Service_result.first",
        "pkg.Service_result.second",
        "pkg.Service_result.Inner_result.call",
    ]

    assert tape.infer_hierarchical_bindings(paths) == {
        "pkg.Service_result": "pkg.Service",
        "pkg.Service_result.Inner_result": "pkg.Service_result.Inner",
    }


def test_load_tape_reads_json_and_validates_it(tmp_path):
    path = tmp_path / "valid-tape.json"
    path.write_text(
        """{
          "session": {
            "sdk": "tapedeck-python",
            "captured_at": "2026-01-02T03:04:05Z",
            "duration_s": 0.5
          },
          "timeline": [
            {"seq": 0, "t": 0.0, "dir": "in", "method": "hello"}
          ],
          "mocked_modules": {},
          "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": true
          }
        }""",
        encoding="utf-8",
    )

    assert tape.load_tape(str(path)) == {
        "session": {
            "sdk": "tapedeck-python",
            "captured_at": "2026-01-02T03:04:05Z",
            "duration_s": 0.5,
        },
        "timeline": [{"seq": 0, "t": 0.0, "dir": "in", "method": "hello"}],
        "mocked_modules": {},
        "metadata": {
            "capture_mode": "value_capture",
            "prefer_return_value": True,
        },
    }


def test_load_tape_rejects_json_that_is_not_a_valid_tape(tmp_path):
    path = tmp_path / "invalid-tape.json"
    path.write_text(
        """{
          "session": {},
          "timeline": [],
          "mocked_modules": {}
        }""",
