def test_build_tape_creates_a_complete_value_capture_document_from_recorder_state():
    class RecorderDouble:
        def __init__(self):
            self.timeline = [
                {"seq": 0, "t": 0.0, "dir": "in", "method": "work"},
                {"seq": 1, "t": 0.2, "dir": "out", "value": "done"},
            ]
            self.events = self.timeline
            self.records = self.timeline

            self.mocked_modules = {
                "demo.Client_result": {
                    "methods": {"work": {"return_value": "done"}}
                }
            }
            self.modules = self.mocked_modules
            self.mock_registry = self.mocked_modules

            self.value_index = {"ref-1": {"name": "saved-value"}}

            self.schemas = {
                "demo.Client_result": {
                    "type": "object",
                    "properties": {"id": {"type": "integer"}},
                },
                "demo.Result_result": {"type": "string"},
            }
            self.nested_schemas = {"wrong.serialization.source": {"type": "null"}}

            # Tape construction must describe the library's value-capture
            # replay contract, rather than copying arbitrary recorder settings.
            self.capture_mode = "reference_capture"
            self.prefer_return_value = False
            self.metadata = {
                "capture_mode": "reference_capture",
                "prefer_return_value": False,
            }

            self.hierarchical_bindings = {
                "demo.Client_result": "demo.Client",
            }

        def get_timeline(self):
            return self.timeline

        def get_mocked_modules(self):
            return self.mocked_modules

    recorder = RecorderDouble()
    session_meta = {
        "sdk": "tapedeck-python",
        "captured_at": "2026-01-02T03:04:05Z",
        "duration_s": 0.2,
    }

    built = tape.build_tape(recorder, session_meta)

    assert built["session"] == session_meta
    assert built["timeline"] == recorder.timeline
    assert built["mocked_modules"] == recorder.mocked_modules
    assert built["value_index"] == recorder.value_index

    # Consumers of a generated tape must be told to use configured return
    # values when replaying value-capture recordings.
    assert built["metadata"] == {
        "capture_mode": "value_capture",
        "prefer_return_value": True,
    }

    # Schemas are serialized from the recorder's schema registry, not from an
    # unrelated similarly named attribute, and are retained as a top-level
    # tape section for consumers that need nested value schemas.
    assert built["nested_schemas"] == {
        "demo.Client_result": {
            "type": "object",
            "properties": {"id": {"type": "integer"}},
        },
        "demo.Result_result": {"type": "string"},
    }
    assert built["hierarchical_bindings"] == {
        "demo.Client_result": "demo.Client",
    }

    assert tape.validate_tape(built) is None

    # The tape is a serialization snapshot: later additions to recorder state
    # must not retroactively appear in an already-built tape.
    recorder.schemas["demo.Added_result"] = {"type": "number"}
    assert "demo.Added_result" not in built["nested_schemas"]
